import { readFile, writeFile } from 'node:fs/promises';
const directory = new URL('./', import.meta.url);
const admin = await readFile(new URL('src/admin.mjs', directory), 'utf8');
const worker = await readFile(new URL('src/worker.mjs', directory), 'utf8');
await writeFile(new URL('worker.js', directory),
  '// Generated by node cloudflare-reviews/build.mjs. Edit src/ instead.\n' +
  admin.replace(/^export const /gm, 'const ') + '\n' +
  worker.replace("import { ADMIN_HTML, ADMIN_JS } from './admin.mjs';", ''));
console.log('Built cloudflare-reviews/worker.js (dashboard-ready, no secrets).');
